using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.FiniteGroups.Semilinear;

internal sealed class WeightedOneSupportStabilizerDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "An actual weighted stabilizer has a nonsplit Galois projection.",
        H("One support, two different group extensions"),
        Blocks(
            Describe.Lean(
                DescribeId.Create("weighted-one-support-internal-structure"),
                DeclarationHandle.Create("D5/S3/FiniteGroups/Semilinear/WeightedOneSupportStabilizer.stabilizer_structure"),
                H("The internal cyclic factors"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Let K be any native finite field algebra over ZMod 5 of cardinality 15625, and let zeta be any primitive field element of order 15624. Its proved nonvanishing defines the unit z. The coordinate type is the entire Fin 5, with weights 5 to the power (i+1) minus 5 plus 1. The coefficient at index 1 is zeta to the power 7, and all other coefficients are zero. S is the actual MulAction.stabilizer for WeightedSemilinear.weightedAction; its scalar sign is the inverse power in the existing action.")),
                    Paragraph(Text("Write f for the native Frobenius automorphism x maps to x to the power 5. In the genuine semidirect group alpha=(z to the power 744,1), tau=(z to the power 8,f squared), and beta=alpha cubed. The fixed-coordinate equation is c to the power 21 times z to the power 7 equals sigma(z to the power 7). These actual elements lie in S; their orders are 21,9,7, respectively, tau cubed is alpha to the power 7, and conjugation by tau sends beta to beta to the power 4.")),
                    Paragraph(Text("The scalar kernel injects into the twenty-first roots of unity. Raising the fixed equation to the power 744 forces the Galois exponent to be even, so the Galois image has order 3. This bounds the order of S by 63. The internal cyclic beta and tau subgroups have coprime orders 7 and 9, so their product injects into S and attains the bound. They are complementary, the beta subgroup is normal, and the native complementary-subgroup construction gives an actual group equivalence from their semidirect product onto S. Its generator action is exponent 4."))),
                DescribeRole.Theorem),
            Describe.Lean(
                DescribeId.Create("weighted-one-support-galois-nonsplitting"),
                DeclarationHandle.Create("D5/S3/FiniteGroups/Semilinear/WeightedOneSupportStabilizer.galois_nonsplitting"),
                H("The Galois projection has no section"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("The actual restriction of SemidirectProduct.rightHom has range exactly the cyclic subgroup generated by f squared, of order 3. Its scalar kernel is the subgroup generated by alpha and has order 21. For every lift g of f squared, not merely the selected tau, its scalar c satisfies c to the power 21 equals z to the power 168. The left component of g cubed is c to the power 651, hence z to the power 5208, which has order 3 and is not one. A group-homomorphic section would lift the order-three generator to an element whose cube is one, contradicting this uniform obstruction.")),
                    Paragraph(Text("Thus the scalar-kernel extension C21 into S onto C3 is nonsplit, even though the same S internally decomposes as C7 semidirect C9. These descriptions use different kernels. The coefficient's primitive-root class and the Frobenius norm force the obstruction; a split ambient scalar-by-Galois group need not induce split stabilizer projections.")),
                    Paragraph(Text("WeightedOrbits.orbit_cardinality supplies the existing quotient-count connection. The finite original-jet orbit bridge connects this action with the corresponding finite quotient, within its own proved hypotheses. The stabilizer result does not prove a factorization of all original automorphisms or any pending arbitrary-universe original-jet statement. Finite-field cyclicity, Frobenius enumeration, root bounds and the native internal semidirect-product assembly are reused from Mathlib; the realized stabilizer and the obstruction for every lift are the new field-action argument."))),
                DescribeRole.Theorem),
            Describe.Lean(
                DescribeId.Create("weighted-one-support-refutes-universal-splitting"),
                DeclarationHandle.Create("D5/S3/FiniteGroups/Semilinear/WeightedOneSupportStabilizer.result"),
                H("A native finite-field counterexample exists"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("The claim that every such stabilizer projection splits is false. The proof uses the actual native GaloisField 5 6, its Mathlib cardinality theorem and cyclicity of its unit group to obtain a primitive element of order 15624. It then applies the uniform lift obstruction. No table model, field enumeration or native-decision axiom is used."))),
                DescribeRole.Theorem))));
}
